return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Basque','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 20:48+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'eu','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" gorde da.','"%1$s" created. %2$d template updated.'=>'"%s" sortu da. %d txantiloia eguneratu da.' . "\0" . '"%s" sortu da. %d txantiloia eguneratu da.','"%s" created.'=>'"%s" sortu da.','"product" (replaces "article")'=>'"produktua" (artikuluaren ordezkoa)','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d karakter — ona, apur bat %2$d ideala baino apur bat gorago baina onartutako %3$d-karaktereko tartean. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d karaktere — luzera ideala. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d karakter — SERPen moztuta egon daiteke (gorde %2$d baino gutxiago). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d karaktere — oso laburra (helburua %2$d–%3$d). %4$s','%1$d internal, %2$d external.'=>'%1$d barne, %2$d kanpoko.','%1$d of %2$d image(s) missing alt text.'=>'%1$d irudi(ak) (%2$d) falta dira alt testuarekin.','%1$d words — below recommended minimum of %2$d.'=>'%d hitz — gomendatuta%1$d hitz — %2$d-ren gutxieneko gomendioa baino gutxiago.ko gutxieneko 300 hitzaren azpitik.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d hitz — eduki oso mehea. Gutxienez %2$d hitzera hedatzea kontuan hartu.','%d chars — good length.'=>'%d karakter — luzera ona.','%d external link(s), no internal links.'=>'%d kanpo esteka(k), barne esteka ez.','%d external link(s), no internal links. Add internal links to related content.'=>'%d kanpoko esteka, ez barneko estekarik. Gehitu barneko estekak lotutako edukira.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 etiketa aurkitu da — orrialde batek H1 bat izan behar du.','%d image(s), all have alt text.'=>'%d irudi, guztiak alt testuarekin.','%d language not yet linked'=>'%d hizkuntza oraindik lotu gabe' . "\0" . '%d hizkuntza oraindik lotu gabe','%d link updated.'=>'%d esteka eguneratu da.' . "\0" . '%d esteka eguneratu da.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d hizkuntza fitxategi ezin izan da automatikoki ezabatu (DISALLOW_FILE_MODS ezarrita dago). Ezabatu eskuz zure zerbitzarian edo WP-CLI bidez: wp language core uninstall <locale>' . "\0" . '%d hizkuntza fitxategi ezin izan da automatikoki ezabatu (DISALLOW_FILE_MODS ezarrita dago). Ezabatu eskuz zure zerbitzarian edo WP-CLI bidez: wp language core uninstall <locale>','%d locale file removed.'=>'%d hizkuntza fitxategi ezabatu da.' . "\0" . '%d hizkuntza fitxategi ezabatu da.','%d locale pack installed.'=>'%d locale pack instalatuta.' . "\0" . '%d locale pack instalatuta.','%d navigation reference updated.'=>'%d nabigazio erreferentzia eguneratu da.' . "\0" . '%d nabigazio erreferentzia eguneratu da.','%d part reference updated.'=>'%d zatiko erreferentzia eguneratu da.' . "\0" . '%d zatiko erreferentzia eguneratu da.','%d words.'=>'%d hitz.','%s Archive'=>'%s Artxiboa','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s aktiboa da eta dagoeneko Schema.org JSON-LD irteera egiten du. Lingua Forge-k bere schema irteera desgaitu du grafiko gatazkak saihesteko. Open Graph-etik desberdina — LF og:locale beste plugin baten irteeraren gainean gehitzen duena — schema ez da modu garbian osatu daitekeena: JSON-LD grafiko bikoitz edo gainidatziak erroreak sortzen dituzte. Desgaitu plugin-an schema irteera nahi baduzu LF-k datu egituratuak kudeatzeko.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s aktiboa da eta bere sitemap propioa sortzen du. Sitemapa hori LF-tik bereizita dago. Biak Google Search Console-ra bidali behar dira: SEO plugin-aren sitemapak zure edukia zerritzen du; LF-ren sitemapak hizkuntza anitzeko estekak gehitzen ditu. LF-ren sitemap-a automatikoki robots.txt-n iragartzen da.','(avg %.1f hits/block)'=>'(batez besteko %.1f iriste/blokea)','(avg %.1f hits/entry)'=>'(batez besteko %.1f eraso/erregistro)','(disabled)'=>'(ezgaituta)','(no title) #%d'=>'(ez du izenbururik) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} ez zuen ordezkagarri dauden loturarik — berriro eskaneatu ikusteko)}','.txt file(s) in the directory'=>'Direktorioan .txt fitxategi(a)','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — ez dago H2 azpi-izendapenik (egokiak edukien mota honentzat).','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — ez da H2 azpiestekarik aurkitu. H2ak gehitzeak egitura hobetzen du.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizatutako txantiloi(ak) &#8220;%2$s&#8221; gaiarekin datu-basean gordeak daude, baina une honetan ez daude aktibo. Aktibatu berriro gaia berreskuratuz gero, aktibo egongo dira. Zure itzulpenak gaia berri horretara eramateko, berriro sortu <strong>Ezarpenak → Lingua Forge → Router → FSE eskema</strong> bidez.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> auto-konpondu daitezkeen lotura','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> eskuz berrikusi behar diren lotura','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> bide zahar(ra)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> txantiloi arazo(ak)','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Webgunean robots.txt fisiko bat dago. WordPress-en robots.txt birtuala — eta LF-ren Sitemap: filter — gainditzen dira. LF-ren sitemap-a ez da bilatzaileei iragartzen.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Only konpilatutako .mo fitxategiak onartzen dira. Fitxategiak {textdomain}-{locale}.mo eredua jarraitu behar du. Fitxategi batek izen bera badu beste batekin, ordeztuko du.','Action'=>'Ekintza','Actions'=>'Ekintzak','active'=>'aktiboa','Active Languages'=>'Hizkuntzak aktiboak','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Hizketan dauden hizkuntzak: gehitu nahi dituzun hizkuntza bakoitza. Hizkuntza bakoitzak URL aurrizki edo azpihostalari bat eta hreflang etiketa bat jasoko du orrialdearen &lt;head&gt;-n.','Active Provider'=>'Hornitzaile aktiboa','Add entry'=>'Gehitu sarrera','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Gehitu jarraibideak zirriborroa hobetu - adibidez, laburtu, laburpen atala gehitu, erabili erregistro formalagoa, FAQ blokea gehitu…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Goratu eskakizunak, adibidez, laburtu, laburpen atala gehitu, erabili formaleagoa...','Add new entry'=>'Gehitu sarrera berria','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Gehitu termino bat lerro bakoitzean. Biak, iturriko terminoa eta helburuko itzulpena, beharrezkoak dira. Pareta hizkuntzak zehazten du zein itzulpen lanetan aplikatzen den muga hori.','Add Sitemap directive to robots.txt'=>'Gehitu Sitemap direktiba robots.txt-ra','Add the following line to your robots.txt manually:'=>'Gehitu lerro hau zure robots.txt-ra eskuz:','Add WooCommerce product tags to Open Graph output'=>'Gehitu WooCommerce produktuen etiketa Open Graph irteeran','Adds a link to the home page so visitors can browse in their language.'=>'Bisitariek beren hizkuntzan nabigatu ahal izateko esteka bat gehitzen du.','Administrators only (manage_options)'=>'Administratzaileak bakarrik (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Hizkuntza nagusia aldatu ondoren, permalinka guztiak bota (beheko atala) URL bideraketa eguneratzeko.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL egitura ezarpenak aldatu ondoren (bidea aurrebista ↔ azpigunea), beti bisitatu Ezarpenak → Permalinks eta sakatu Gorde Aldaketak birkargatzeko erreibatu arauak.','AI analysis failed. Please try again.'=>'AI azterketa huts egin du. Saiatu berriro.','AI Behaviour Preset'=>'AI Portaera Aurrebista','AI cache cleared. %d entry was removed.'=>'AI cachea garbitu da. %d sarrera ezabatu da.' . "\0" . 'AI cachea garbitu da. %d sarrera ezabatu dira.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: AI erantzunen cachea eta eraso kopuruen zerrenda. Garbitu cache osoa edo post baten sarrera bakarra. Erabili "Garbitu" itzulpen aldaketa probatu aurretik — cacheko emaitzak itzultzen dira, AI preset edo modelo aldatzen duzun arte, cacheko sarrera kendu arte.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI ezaugarriak aukerakoak dira. Hizkuntzen bideraketa, hreflang, hizkuntzaren switcher eta itzulpen taldea sistema guztiak lan egiten dute hornitzailearen konfigurazio gabe.','AI Limits & Security'=>'AI Muga eta Segurtasuna','AI provider returned an empty response.'=>'AI hornitzaileak erantzun hutsa eman du.','AI Recommendations'=>'AI gomendioak','AI returned an unexpected response format. Please try again.'=>'AI-k erantzun format ezezaguna itzuli du. Saiatu berriro.','AI Usage'=>'AI Erabilera','AI Usage & Cache'=>'AI erabilera eta cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Helburu 120–160 karakteretan. Utzi hutsik zatia erabili nahi baduzu.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Bilaketa-makinek — Google, Bing eta Yandex — automatikoki aurkitzen dute sitemap: direktiboa robots.txt-n. Ez dago eskuzko ekintzarik behar. Beheko botoiek ping bat bidaltzen dute orain sitemap berriro arakatzeko, hurrengo robots.txt egiaztapenaren zain egon beharrik gabe.','All time'=>'Denbora guztian','All types'=>'Mota guztietarako','Allow editors to lock individual blocks'=>'Baimendu editoreek bloke bana blokeatzea','Allow Gutenberg template-editing mode on post screens'=>'Baimendu Gutenberg-eko txantiloi editatzeko modua mezularitza pantailetan','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Era berean, ezabatu hizkuntza esleipenak, itzulpen harremanak, meta deskribapenak, glosarioa eta Itzulpen Memoria plugin-a desinstalatzen denean.','Also generate meta description'=>'Era berean, sortu meta deskribapena','Alternative (server-side):'=>'Alternatiba (zerbitzarian):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Betiko emititu og:locale eta og:locale:alternate. Beste plugin edo gaia OG osotasuna kudeatzen duenean erabili.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Betiko emititu OG + Twitter Card osotasuna, beste plugin-ik ez badago. Erabili plugin-ik ez badago OG etiketa irteten.','An unknown error occurred.'=>'Errore ezezaguna gertatu da.','Analyse…'=>'Aztertu…','Analysis'=>'Analisi','Analysis request failed. Please try again.'=>'Analisi eskaera huts egin du. Saiatu berriro.','Analyzing…'=>'Aztertzen…','and'=>'eta','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'edozein','API calls saved by cache'=>'API deien gordetakoak cache bidez','API Key'=>'API Giltza','API Keys'=>'API giltzak','API Keys Tab'=>'API Gakoen Fitxa','API Response Cache'=>'API Erantzun Cachea','Appends the following line to your existing robots.txt: %s'=>'Gehitu zure robots.txt-ra lerro hau: %s','Applied ✓'=>'Aplikatua ✓','Apply failed — please try again.'=>'Aplikazioa huts egin du — mesedez saiatu berriro.','Apply to Block'=>'Aplikatu blokean','Apply to Editor'=>'Aplikatu Editoreari','Apply to Footnote'=>'Aplikatu ohar notan','Apply to Meta Description'=>'Aplikatu Meta Deskribapenera','Apply translation'=>'Aplikatu itzulpena','Applying…'=>'Aplikatzen…','Approximate size'=>'Tamaina hurbila','Archive'=>'Artxiboa','Archive: %s'=>'Artxiboa: %s','Article / WebPage'=>'Artikulua / Web orria','Article / WebPage — all singular posts and pages'=>'Artikulua / Web orria — post eta orri singular guztiak','Authors and above (edit_published_posts)'=>'Egileak eta gehiago (edit_published_posts)','Auto (recommended)'=>'Auto (gomendatua)','Behavior'=>'Jokabidea','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Jokabidea: aukeratu AI preset (Literal, Balanced, Creative), gehitu webguneko prompt-instrukzio pertsonalizatuak, gaituta edo desgaituta utzi automatikoki postaren gordailuaren itzulpena, eta konfiguratu Itzulpen Memoria.','Block Content'=>'Blokearen edukia','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Uneko orria bere jatorrizko hizkuntzan erakusten du, ez dagoelako itzulpenik bisitariaren hizkuntzarako. Lingua Forge router-aren LINGUAFORGE_LANG_FALLBACK_ACTIVE seinalearen bidez kontrolatzen da — ez du ezer emititzen eskaeraren hizkuntzarako itzulpenik badago.','Block Editor'=>'Bloke Editorea','block keywordfallback'=>'falta','block keywordi18n'=>'i18n','block keywordlanguage'=>'hizkuntza','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'itzulpena','Block locking'=>'Blokearen blokeatzea','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Ezarritako blokeak post moten pertsonalizatuak. Erabili Itzuli botoia hizkuntza bertsioa sortzeko. Edukia itzulita hemen gordetzen da eta CPT post batean kopiatu daiteke blokea editorearen Pattern inserter-etik edo erabil daiteke Pattern Sinked (Erabilgarri Blokea) hasteko.','block titleMissing Translation Notice'=>'Hitzordua falta den oharraren jakinarazpena','Block translation reuses'=>'Bloke itzulpenaren erabilerak','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Bloke mailako itzulpen cachea post guztietan partekatua. Gaituta, bloke berdinak (marko bera, hizkuntza pareta, eta glosarioa) memoriaetik ematen dira AI berriro deitu beharrik izan gabe. Konfiguratu Ezarpenak → Jokabidea.','Blog / Editorial'=>'Blog / Edizioa','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blog postak Artikulua erabiltzen du; beste post mota eta orriak WebPage erabiltzen dute. Titulua, deskribapena, inLanguage, url, dataArgitaratua, dataAldatuta, irudia, eta argitaratzailea barne.','Browser language redirect'=>'Nabigatzailearen hizkuntzaren birzirkulazioa','Built-in preset instructions:'=>'Prestatutako ezarpenak: ','Bulletize (•-prefixed)'=>'Buleta (•-rekin hasita)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache itzulpen baliokideak bloke mailan, eduki erabili daitekeenak (oina, alboak, akordeoiak, lege-oinarriak) API deia egin gabe. Aktibatuta, itzulpen fluxuak post bakoitza bloketan banatzen du, cache-an bilatzen du eta blokez kanpokoak AI-ra bidaltzen ditu eskaera batean. Glosario editaketak eta Betetze aurreko aldaketak automatikoki baliogabetzen dituzte cacheko itzulpenak. Estatistikak ikusi eta cachea garbitu Mantentzean.','cached'=>'Gordeta','Cached API responses'=>'Cacheko API erantzunak','Cached block translations'=>'Cacheko bloke itzulpenak','Cancel'=>'Ezeztatu','Cannot determine target language from slug.'=>'Ezin da helburu hizkuntza slug-etik zehaztu.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Ezin izan da idatzi produktua %1$d-ra: itzulitako bertsioa da (hizkuntza: %2$s)%3$s. Datu operatiboak (prezioa, stocka, SKU, dimentsioak) iturri produktuan eguneratu behar dira. Eguneratu iturri produktua ID bidez: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Kanonikoa etiketa','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Murriztu AI erabilera muga eta baimendu erabiltzaile rol batzuk AI bidezko deien kostuak kontrolatzeko. Erabiltzaile bakoitzeko tasa-muga gainditzen du (30 eskaera / minutua, kodean ezarrita), eta bakarrik erabiltzaile bakarraren abiadura kontrolatzen du.','chars'=>'karaktereak','Chunk translated'=>'Zati itzuli','Chunk translated to:'=>'Zati itzuli da:','Clear'=>'Garbitu','Clear All'=>'Garbitu guztiak','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Garbitu AI cacheko emaitza guztiak? Etorkizuneko eskaerak API deia berriro eragingo du cachea berritzen den arte.','Clear API Response Cache'=>'Garbitu API Erantzun Cachea','Clear Debug Files'=>'Garbitu Debug Fitxategiak','Clear hints'=>'Garbitu aholkuak','Clear input'=>'Garbitu sarrera','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Garbitu Itzulpen Memoria osoa? Etorkizuneko itzulpenek cachea berriro eraikiko dute.','Clear Translation Memory'=>'Garbitu Itzulpen Memoria','Close'=>'Itxi','Close language panel'=>'Itzuli panel hizkuntza','Close popover'=>'Itxi popover','Compatibility'=>'Gaitutasuna','Compliance Preset'=>'Betetze aurrekoa','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Konfiguratu AI hornitzailea Ezarpenak → API giltzak atalean AI gomendioak aktibatzeko.','Content generated'=>'Edukia sortu da','Content Generator'=>'Eduki Sortzailea','Content ready'=>'Edukia prest dago','Contributors and above — default (edit_posts)'=>'Garatzaileak eta gehiago — lehenetsia (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Nola kontrolatu edukiaren kantitatea AIra bidaltzen dena eta erantzunaren tamaina. Utzi hutsik, balio lehenetsia erabiltzeko. Handitu balioak orri handiak moztu badira; jaitsi API kostuak murrizteko.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI Eduki Sortzailearen token aurrekontua eta sarrera mugak kontrolatzen ditu. Utzi eremuak hutsik, ezarritako balioekin erabiltzeko.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kudeatzen du zer gertatzen den administratzaileak plugin-a ezabatzen duenean Plugins → Installed Plugins → Delete. Pluginaren ezarpenak eta AI cache-ak beti ezabatzen dira. Hizkuntza esleipenak eta itzulpen harremanak mantentzen dira lehenetsita, beraz, desinstalazio edo berrinstalazio batetik bertara itzuli daiteke.','Conversational'=>'Egunerokoa','Copied ✓'=>'Kopiatu ✓','Copy'=>'Kopiatu','Copy failed — please copy the URL manually.'=>'Kopiatu huts egin du — kopiatu URL-a eskuz.','Copy markup'=>'Kopiatu markaketa','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopiatu uneko URL-a arbelean. Zorionak, "Link copied" mezua erakutsiko da arrakastaz.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Kopiatu emaitza eta itsatsi behar den lekuan (adibidez, zuzenean azpiko eremuan).','Copy to safe storage'=>'Kopiatu segurtasun gunean','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopiatu/natibo/auto JS ekintzak: LF-ren social-share.js-k kudeatzen ditu','Could not add entry: source term and target term are required.'=>'Ezin izan da sarrera gehitu: iturri terminoa eta helburu terminoa beharrezkoak dira.','Could not copy the file. Check that the uploads folder is writable.'=>'Ez da fitxategia kopiatzen. Egiaztatu upload karpeta idazgarria dela.','Could not instantiate the provider.'=>'Ezin izan da hornitzailea sortu.','Could not save the file. Check that the uploads folder is writable.'=>'Ez da fitxategia gorde. Egiaztatu upload karpeta idazgarria dela.','Could not save the glossary entry.'=>'Ezin izan da glossario sarrera gorde.','Could not write to robots.txt. Check file permissions.'=>'Ezin izan da robots.txt-ra idatzi. Fitxategi baimenak egiaztatu.','CPT Block Patterns'=>'CPT Bloke Patternak','Create'=>'Sortu','Create missing'=>'Sortu gabeak','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" post motarako itzulpenak sortzea aktibo dagoen integrazio bat behar du. Mesedez, ziurtatu integrazioa instalatuta eta aktiboa dagoela.','Creating…'=>'Sortzen…','Creative / Marketing'=>'Sortzailea / Marketina','Creative / Marketing instructions'=>'Kreatiboa / Marketin argibideak','Current content (will be overwritten)'=>'Uneko edukia (gaur egun ordezkatuko da)','Current status'=>'Uneko egoera','Current title'=>'Uneko izenburua','Current: {current}'=>'Unekoa: {current}','Currently emitting'=>'Une honetan emititzen','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Une honetan %s konstantea heredatzen da. Hemen balioa hautatzeak gaindituko du.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Une honetan ez da erabiltzen, post-aren atributuaren placeholder-ak (wp:details laburpen eremuak, etab.) erabiltzen dituztenak — existitzen den itzulpen bide bakarrean pasatzen dira.','Currently:'=>'Unean','Custom'=>'Pertsonalizatua','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'AI egutegiko kuota bete da (%1$d eskaera). Resetatzen da %2$s UTC-tan.','Daily request limit'=>'Eguneko eskaera muga','Danger Zone'=>'Arriskuen zona','Debug Files'=>'Debug Fitxategiak','Debug files cleared. %d file was removed.'=>'Debug fitxategiak garbitu dira. %d fitxategi bat kendu da.' . "\0" . 'Debug fitxategiak garbitu dira. %d fitxategi kendu dira.','Debug logging'=>'Debug log-ak','Debug logging disabled.'=>'Debug log-ak desaktibatuta daude.','Debug logging enabled.'=>'Debug log-ak aktibatuta daude.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: gaitu debug erregistroa AI promptak eta API erantzunak lokaleko fitxategi batean harrapatzeko. Desgaitu arazoak konpontzeko — debug moduak fitxategi bat idazten du AI eskaera bakoitzean.','Default OG image'=>'OG irudi lehenetsia','Delete'=>'Ezabatu','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Ezabatu debug direktorioan dauden .txt fitxategi guztiak? Direktorioa bera geratuko da, etorkizuneko debug idatziak garbi iritsi daitezen.','Delete all files for this override (both .mo and .po)?'=>'Ezabatu fitxategi guztiak ordezkaritza honetan (biak .mo eta .po)?','Delete content data on uninstall'=>'Ezabatu edukien datuak desinstalazioan','Delete this glossary entry?'=>'Ezabatu glossario sarrera hau?','Describe what to write — topic, key points, structure…'=>'Deskribatu zer idatzi behar den — gaia, gako puntuak, egitura…','Details ↗'=>'Xehetasunak ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detektatu aktibo SEO pluginak (Yoast, Rank Math, etab.) exekuzioan. Emititu og:locale + og:locale:alternate bakarrik beste plugin batek OG osotasuna ematen duenean; emititu osotasuna ez dagoenean.','Directory'=>'Direktorioa','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Desgaitu prompt tuning-ean edo behar duzunean AI hornitzailearengana eskaerak iristeko. Desgaituak cacheko sarrera ezabatzen ez ditu, berriro aktibatzeak berreskuratzen ditu. API gastua handitzea espero da, batez ere gune busyetan, desgaituta dagoenean.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Desaktibatu soilik headless guneetan edo hreflang inplementazio osoetan. Desaktibatuta, LF ez du WordPressen kanonikoa etiketa kentzen edo SEO-pluginen hreflang outputa ezkutatzen.','Disabled'=>'Desaktibatuta','Disabled (by setting)'=>'Desaktibatuta (ezarpen bidez)','Disabled (mode setting)'=>'Desaktibatuta (modu ezarpen bidez)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Desaktibatuta dago LF-social-share mu-plugin honek jada funtzio hori eskaintzen duelako.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS ezarrita dago.','Display'=>'Erakutsi','Displays the Lingua Forge language switcher.'=>'Lingua Forge hizkuntza aldatzailearen pantaila erakusten du.','Do not output any OG tags.'=>'Ez izan OG etiketa inor ere ematen.','Documentation'=>'Dokumentazioa','Done'=>'Eginda','Done — {done} of {total} post(s) fixed.'=>'Eginda — {done} post eta orri {total} konponduta.','Down'=>'Behera','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Deskargatu eta instalatu WordPressen hizkuntza pakete nagusia WordPress.org-etik. Instalatu ondoren, locale-a URL bidegurutze eta AI itzulpen lanerako erabilgarri izango da. Eskuragarri dauden hizkuntzen zerrenda eskakizunaren arabera lortzen da — sakatu beheko botoia kargatzeko.','Dropdown direction'=>'Dropdown norabidea','edit'=>'Editatu','Editors and above (edit_others_posts)'=>'Editoreak eta gehiago (edit_others_posts)','Enable API response caching'=>'Gaitu API erantzunen cachea','Enable block-level translation cache reuse across posts'=>'Bloke mailako itzulpen cache erabili beste postetan','Enable Social Share URL rewriting for Social Icons blocks'=>'Gaitu Social Share URL berridazketa Social Ikono bloketan','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Gaitu zure gaiak postaren izenburua H2 bezala renderizten duenean, H1 ordez (batzuetan bloke gaietan ohikoa). Analiszaileak orri renderizatua jasotzen du eta, H1 ez badago baina H2 badago, lehenengo H2 H1-ra igotzen du puntuatzeko.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Sartu zure API gakoa gutxienez AI hornitzaile batean. Gakoak AES-256-GCM erabiliz enkriptatzen dira atsedenaldian, gune bereziko sekretu batekin (LINGUAFORGE_SECRET). Ez partekatu datu-base esportazioak sekretua lehenengo birrortzen ez baduzu.','environment variable'=>'ingurune aldagaia','Error'=>'Errorea','Expand'=>'Zabaldu','Expected: {expected}'=>'Itxaron: {expected}','External share services'=>'Kanpoko partekatze zerbitzuak','Extra guidance — tone, style, constraints, target audience…'=>'Gida osagarria — tonua, estiloa, murrizketak, helburu publikoa…','Extra guidance — tone, style, constraints…'=>'Gida osagarria — tonua, estiloa, murrizketak…','Failed. Please try again.'=>'Huts egin du. Saiatu berriro.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Orri batean ez dagoen irudiaren URL alternatiboa, gunearen logo edo ikonoa. Gizarte aurreikuspenetan erakusten da artxibo, blogen hasiera eta orri singular batean thumbnail gabe.','Feature'=>'Ezaugarri','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Ezaugarriak bi mailatan banatzen dira. Sartu bakoitzaren identifikadore zehatza eta hornitzailearen izena. Utzi hutsik, lehenetsia erabiltzeko. Aktibo den hornitzailearen modeloak bakarrik deitzen dira exekuzioan — besteak aurretik konfiguratu behar dira aldatzeko.','File copied to safe storage successfully.'=>'Fitxategia arrakastaz kopiatuta segurtasun gunean.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Fitxategi aldaketak desgaituak daude (DISALLOW_FILE_MODS).','Files'=>'Fitxategiak','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Fitxategiak beheko direktorian kokatzen dira. Itzulpen arazoak diagnostikatzeko erabilgarria — itzali behar duzu behar duzuna lortu arte, bestela fitxategiak handitzen dira. Hau behartu dezakezu wp-config.php-tik `define( \'LINGUAFORGE_AI_DEBUG\', true );` erabiliz, toggle hori gainetik.','Filter'=>'Filtroa','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Hizkuntzaren eta post motaren arabera iragazi, zure edukia arakatu, eta klikatu Analyze edozein elementutan SEO audit bat egiteko — tituluaren luzera, meta deskribapena, hitzen kopurua, goiburu egitura, irudiaren alt estaldura, eta barne loturak.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtratu linguaforge_debug_dir erabiliz, debug irteera ezkutuko kokapen batera bideratzeko.','Finding'=>'Bilaketa','Fix'=>'Konpondu','Fix All'=>'Konpondu Guztiak','Fix all links'=>'Konpondu estekak guztiak','Fix all parts'=>'Konpondu atal guztiak','Fix Links'=>'Aldatu Estekak','Fix Nav'=>'Aldatu Nabigazioa','Fix Parts'=>'Aldatu Zatiak','Fix Template'=>'Konpondu Txantiloa','Fixing {n} / {total}…'=>'{n} / {total} konpontzen…','Fixing…'=>'Konpontzen…','Flush Permalink Rules'=>'Bota Permalink Arauak','Flush Permalinks'=>'Bota Permalinks','Flush Sitemap Cache'=>'Sitemap Cachea hustu','Footnote Content'=>'Ohar notaren edukia','footnote(s) translated — applied together with content.'=>'Azpi-oinak itzuli dira — edukiarekin batera aplikatuta.','Footnotes'=>'Azpi-oinak','Footnotes payload (advanced)'=>'Ohar zinta ( aurreratua)','Forbidden'=>'Aurreikusi gabe','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Hurrengo eskaeran sitemap-a berriz sortzeko behartzen du. Masiboki inportatu edo itzulpen erlazioak eskuz editatu ondoren erabiltzeko.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Aurkitutako {parts} {total} postetan eta {scanned} aztertu direnetan {lang} hizkuntzarako.','From'=>'Nondik','Front Page'=>'Lehentasuna Orria','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE lokalizazioa: eskema, itzuli, eta konpondu estekak Full Site Editing txantiloi eta zatietan zuzenean taula honetan.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktiboen gaian oinarritutako FSE txantiloiak. Sortu eta pertsonalizatu Webgune Editorean.','Full'=>'Bete','Full Article'=>'Artikulu osoa','Full post'=>'Post osoa','General'=>'Orokorra','Generate'=>'Sortu','Generate Content'=>'Sortu Edukia','Generate content…'=>'Edukia sortu…','Generate Excerpt'=>'Sortu Aipamena','Generate Meta Description'=>'Sortu Meta Deskribapena','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Sortu hizkuntza anitzeko sitemap-a /lf-sitemap.xml helbidean','Generated Content'=>'Sortutako Edukia','Generated meta description'=>'Sortutako meta deskribapena','Generating…'=>'Sortzen…','Generation failed.'=>'Sortzea huts egin da.','Getting started'=>'Hasi','Global AI preset'=>'AI aurrekoa globala','Global default (%s)'=>'Nazioarteko lehenetsia (%s)','Glossary'=>'Glosario','Glossary entry added.'=>'Glossario sarrera gehitu da.','Glossary entry removed.'=>'Glossario sarrera ezabatu da.','Glossary Tab'=>'Glosarioaren Fitxa','Google (Gemini)'=>'Google (Gemini)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-H1 modua aktibatuta — izenburua H1 berdina kontatzen da. (Izenburu etiketak ezin izan dira detektatu renderizatua den orritik; egiaztatu zure gaiak izenburua behar bezala ematen duela.)','Headings'=>'Goiburuak','Hide'=>'Ezkutatu','Hints'=>'Gomendioak','Home link text'=>'Hasierako estekaren testua','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Itzulpenan nola agertu behar duen. Iturri terminoa berdin gordetzeko AIri instrukzioa emateko, balio bera eman itzultzeko.','How to use'=>'Nola erabili','Hreflang'=>'Hreflang','Hreflang output'=>'Hreflang outputa','Hreflang settings saved.'=>'Hreflang ezarpenak gorde dira.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikono + etiketa','Icon only'=>'Ikono bakarra','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Egiaztatzen baduzu, plugin-a desinstalatzen duzunean, hizkuntza esleipen guztiak, itzulpen harremanak, meta deskribapenak, orrialdeko aurresetak, AI glosarioa eta Itzulpen Memoria betirako ezabatuko dira gune honetan. Hau ezin da desegin. Ez egiaztatu, gunean aniztasun hizkuntzak guztiz ezabatu nahi baduzu.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'SEO plugin orokor bat instalatuta baduzu, panel honek LF nola egokitzen den ikusiko du bikoizketa outputa saihesteko. Helburua talka saihestea da — ez lankidetza. LF beti ematen du hizkuntza anitzeko SEO geruza (hreflang, og:locale, inLanguage schema) behar duena LF-ren hizkuntza bideraketa konfigurazioaren ezagutza behar duena.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Yoast SEO, Rank Math, All in One SEO edo SEOPress instalatuta badago, Lingua Forge detektatzen du eta egokitzen du bikoizketa outputa saihesteko. Hreflang-rako, LF hartzen du guztiaz eta pluginaren outputa ezabatzen du, pluginek ezin baitute hizkuntza anitzeko bideraketa konfigurazio egokirako hreflang zuzena sortu. Open Graph-rako, LF-k og:locale eta og:locale:alternate soilik gehitzen ditu — pluginak ezin dituen hizkuntza anitzeko seinaliak — eta OG oinarrizko multzoa pluginarentzat uzten du. Schema.org-rako, LF-k bere irteera guztia desgaitu du JSON-LD grafikoen aurkako talka saihesteko.','Images'=>'Irudiak','Improve writing'=>'Hobetu idazketa','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Bloke editorean, Gehitu Social Icons blokea. Ikono bakoitzerako, ireki estekaren ezarpenak eta sartu behean "share:" balioetako bat URL gisa. Aurrealdean, LF-k ordezkatzen du orriaren egokirako partekatze URL egokiarekin.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Izena, deskribapena, inLanguage, url, irudi, eta Offer bat barne hartzen ditu prezioa, prezio moneta, eta eskuragarritasuna. Prezioa eta eskuragarritasuna iturri-hizkuntzako produktutik datoz (partekatutako stock eredua).','Includes site name, url, and inLanguage.'=>'Gune izena, url, eta inLanguage barne hartzen ditu.','Informative'=>'Informativo','Input tokens'=>'Sarrerako tokenak','Install'=>'Instalatu','Install a Language'=>'Hizkuntza bat instalatu','Installed SEO plugins'=>'SEO pluginak instalatuta','Installing…'=>'Instalatzen…','instock / oos / pending from WC stock status'=>'In stock / oos / pending WC stock egoeratik','Instructions (optional)'=>'Argibideak (aukerakoa)','Instructions / key points'=>'Argibideak / gako puntuak','Integration API'=>'Integrazio API','Internal Link Fixer'=>'Barneko Lotura Konpontzailea','Introduction only'=>'Sarrera soil','Invalid file reference.'=>'Fitxategi erreferentzia baliogabea.','Invalid filename.'=>'Fitxategi izenburu baliogabea.','Invalid language code.'=>'Hizkuntza kode baliogabea.','Invalid language.'=>'Hizkuntza baliogabea.','Invalid locale code.'=>'Hizkuntza kode baliogabea.','Invalid or primary language.'=>'Hizkuntza baliogabea edo lehenetsia.','Invalid post ID.'=>'Post ID baliogabea.','Invalid post type.'=>'Post motaren errorea.','Invalid template part.'=>'Txantiloia zatia baliogabea.','Invalid template type.'=>'Txantiloia mota baliogabea.','JavaScript-powered actions'=>'JavaScript bidezko ekintzak','Key points, ideas, or structure to build from…'=>'Puntu nagusiak, ideiak edo eraikitzeko egitura...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Giltzak AES-256-CBC enkriptatzen dira WordPress datu-basean gordetzeko. Enkriptazio sekretua zure WordPress autentifikazio gatz-iturrietatik dator (wp-config.php), beraz, testu hutseko giltzak ez dira inoiz datu-basean jartzen.','Landing / Short-form'=>'Landa / Motz-forma','Language'=>'Hizkuntza','Language %s installed successfully.'=>'Hizkuntza %s arrakastaz instalatu da.','Language (optional)'=>'Hizkuntza (aukerakoa)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian (DISALLOW_FILE_MODS ezarrita dago).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian. DISALLOW_FILE_MODS konstantea wp-config.php-n ezarrita dago. Instalatu hizkuntza paketeak eskuz WP-CLI bidez: wp language core install de_DE','Language label'=>'Hizkuntza etiketa','Language Overrides'=>'Hizkuntza Aldaketak','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Hizkuntzen Aldaketak: kudeatu zure .po/.mo fitxategi pertsonalizatuak Lingua Forge UI-rako. Erabili hau plugin fitxategiak zuzenean editatu beharrean — aldaketak bizirauteak iraun dezake.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Hizkuntza paketea instalatzea huts egin du. Hizkuntza jada instalatuta egon daiteke, locale kodea okerra izan daiteke, edo zure zerbitzariak fitxategien idazketa bloke dezake.','Language Setup'=>'Hizkuntza konfigurazioa','Language Switcher'=>'Hizkuntza Aldatzen','Language switcher'=>'Hizkuntzen switcher','Language uninstalled. %d post deleted.'=>'Hizkuntza desinstalatu da. %d posta ezabatu da.' . "\0" . 'Hizkuntza desinstalatu da. %d post ezabatu dira.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Gaia-oinarritutako kopiak, hizkuntzaren arabera. Eskemak sortu ondoren, txantiloiak hizkuntzaren arabera eguneratzen dira.','Language:'=>'Hizkuntza:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Router-ek ezagutzen dituen hizkuntzak (WordPressen locale paketeak eta oinarrizko hizkuntza). Instalatu hizkuntza pakete gehiago beheko atalean, bidegurutze eta itzulpenetarako gehiago hizkuntza erabilgarri egiteko.','Last 30 days'=>'Azken 30 egun','Last 7 days'=>'Azken 7 egun','Last generated: %s'=>'Azkeneko sortzea: %s','Lead paragraph (≤60 w)'=>'Lehen paragrafoa (≤60 hitz)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Utzi modelo eremua hutsik, eta erabil ezazu eraikitako lehenetsia maila horretarako. Lehenetsia testuaren ordezkoa erakusten du.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Utzi hutsik marken izenak eta hizkuntzarekiko ezberdintasunak ez diren terminoa betetzeko, itzultzen garenean.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Utzi hutsik, sarrera hau guztietara aplikatzeko — marka izenak, laburdurak eta beti berdin gordetzeko terminoa.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Utzi hutsik eginez gakoa mantentzen da. Sartu balio berri bat ordezkatzeko.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Utzi hutsik erabiltzeko ezarritako lehenetsia. Gorde aurretik ezarritako aldaketa ezabatzeak lehenetsia berreskuratuko du hurrengo gordetzean.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin detektatu da. LF-k oinarrizko OG multzoa mu-plugin-era atzeratzen du eta og:locale + og:locale:alternate bakarrik ematen ditu. Mu-plugina deaktibatu dezakezu — LF-ren Gizarte Partekatze (SEO → Gizarte Partekatze fitxa) eta Open Graph funtzionalitatea berdinak dira.','Legal / Compliance'=>'Juridikoa / Betetze','Legal / Compliance instructions'=>'Lege / Betetze argibideak','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF beti gehitzen du og:locale eta og:locale:alternate — hizkuntza anitzeko OG seinaliak ez duela plugin orokor batek zuzenean sortu. Oinarrizko OG multzoa (og:title, og:description, og:image) ematen du plugin gabe dagoenean. SEO plugin bat instalatuta badago, LF-k multzo nagusia saihesten du bikoizketa etiketa sortzeko — ez pluginak "hobe" direlako, baina bikoizketa ez duelako baliorik sortzen.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF-k bere sitemap propioa sortzen du xhtml:link alternatibekin denbora-talde guztientzat. SEO plugin bat instalatuta badago, sitemap bereizi bat sortzen du — biak independente daude. Bidali biak Google Search Console-era: SEO pluginaren sitemap edukia aurkitzeko, LF-ren sitemap hizkuntza erlazio seinalerako.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF-k hreflang etiketa ematen du eta WordPressen kanonikoa etiketa ezabatu du hizkuntza anitzeko orrietan.','LF is suppressing hreflang output from: %s'=>'LF-k hreflang outputa ezkutatzen du: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LFk eraginkortasunez ematen du hreflang denak konfiguratutako hizkuntzarako, x-default barne. SEO plugin orokorrak ez du zure LF bideratze konfigurazioan sarbiderik eta hreflang akats URL okerretan oinarrituta sortuko luke. LF haien irteera ezabatzen du iragazki bidez talka ekiditeko.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LFk JSON-LD anitz hizkuntzazkoak ematen ditu hizkuntza anotazioekin, bere bideratze konfigurazioarekin lotuta. SEO plugin bat instalatuta dagoenean, LFk bere schema guztiz desgaitu egiten du: JSON-LD grafiko bikoitzek baliozkotze erroreak sortzen dituzte eta grafiko existitzen bati osagarri bat jartzeko modu garbirik ez dago.','LF provides'=>'LFk ematen du','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LFk WordPressen kanonikoa den etiketa kentzen du hizkuntza anitzeko orrietan, router-aren hizkuntza-prefikseko berridazketa arauak eta hreflang x-default-ek hizkuntza anitzeko webgune baterako seinalizazio kanonikoa direla. Honek saihesten du kanonikoa bikoitza izatea SEO plugin batek ere kanonikoa ematen badu. LFk bere kanonikoa ezartzen ez du — hizkuntza bideratzeak URL bakoitza kanonikoa egiten du jada.','Light'=>'Argia','Light (default — fast and cost-effective)'=>'Arina (lehena — azkar eta kostu txikia)','Light (fast and cost-effective — Haiku / Flash)'=>'Argia (azkar eta kostu eraginkorra — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Argia: erabiltzen da meta deskribapenak eta laburpenak sortzeko — azkarra, kostu baxua.','Limit results to pages in the given Lingua Forge language code.'=>'Mugatu emaitzak Lingua Forge hizkuntza kodean dauden orrietan.','Limits'=>'Muga','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge zure WordPress gunean hizkuntza anitzeko bideraketa, AI bidezko itzulpena, hreflang SEO etiketa eta hizkuntzaren switcher gehitzen ditu.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge-k WooCommerce-aren Open Graph propietate espezifikoak produktu orrietara gehitzen ditu, Facebook, Pinterest eta antzeko plataformetan produktuaren URL-a partekatzean, produktuaren mota, prezioa eta eskuragarritasuna agertzeko.','Lingua Forge AI Tools'=>'Lingua Forge AI tresnak','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge WordPressen Gizarte Ikonoen blokea zabaldu du, URL partekatzeko dinamikako estekekin. Edozein ikono lotura "share:" balioarekin ezarri eta LFk berridazten du egokieneko partekatzeko URL edo JavaScript ekintza batean — ez da beharrezkoa kode pertsonalizatua edo hirugarren plugin bat.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge-k XML sitemap bereizi bat sortzen du /lf-sitemap.xml helbidean, zure itzuli den eduki guztirako hizkuntza alternatibako estekak gehituz. Sitemapa honek WordPressen sitemap nagusia eta edozein SEO plugin-en sitemap osatzen ditu — ez ditu ordezkatzen.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge soluzio osoa da hizkuntza anitzeko SEO-rako. Ez da beste SEO plugin bat behar.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge soluzio osoa da hizkuntza anitzeko SEO-rako. Ez da beste SEO plugin edo sitemap plugin bat behar.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge-k hizkuntza guztietarako <link rel="alternate" hreflang> etiketak sortzen ditu orri bakoitzean, x-default iturriko hizkuntzara zuzenean bideratuta dagoena barne, eta hau Google eta beste bilaketa-motorentzako SEO seinalea nagusia da — ez dago SEO plugin gehigarririk beharrezkoa.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge Open Graph eta Twitter Card meta etiketak ematen ditu, URL partekatuek hizkuntza, titulua, deskribapena eta irudia sozial plataformetan egokiak erakusteko.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge-k Schema.org JSON-LD datu egituratuak ematen ditu, bilatzaileek zure edukiaren mota, hizkuntza eta metadatuak ulertzeko. Hau da Google eta beste arakatzaileentzat hizkuntza anitzeko edukiaren anotazioak komunikatzeko modurik nagusia.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge-k Gutenberg bi ezaugarri mugatzen du lehenetsian, hizkuntza arteko jokabidea koherente mantentzeko. Aukeratu hemen zuretzat beharrezkoa den Gutenberg / FSE gaitasun osoa izateko.','Lingua Forge Settings'=>'Lingua Forge Ezarpenak','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge-k bi cache geruza independente erabiltzen ditu AI API deien errepikapenak saihesteko. Erabili beheko fitxak bakoitza aztertzeko eta kudeatzeko.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge-k bi modelo maila erabiltzen ditu hornitzaile bakoitzeko:','Lingua Forge — Quick Translate'=>'Lingua Forge — Azkar Itzuli','Lingua Forge — Settings'=>'Lingua Forge — Ezarpenak','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge-ren Gizarte Partekatze eta Open Graph moduluak mu-plugin-ek eskaintzen duen funtzionalitatea guztia estaltzen du, baita og:locale anitzak ere. Seguru dezakezu mu-plugina desgaitu dezakezula.','Link copied'=>'Esteka kopiatu da','link(s)'=>'lotura(ak)','Links'=>'Loturak','Load available languages'=>'Kargatu hizkuntza erabilgarriak','Load content'=>'Edukia kargatu','Loaded from cache.'=>'Kaxatik kargatuta.','Loading…'=>'Kargatzen…','Locale only'=>'Bakarrik hizkuntza','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Blokeatuta — SEO plugin bateren batek aktibuta dago. Ikusi goiko oharra.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate bere itzulpen pertsonalak wp-content/languages/loco/ kokatzen ditu — leku hori WP eguneraketak, plugina berrabiarazteak edo Loco Translate ezabatzeak ezabatzen du. Fitxategiak hemen kopiatzeak Lingua Forge i18n-overrides direktorioan jartzen ditu, eta horrek iraun duzuen bitartean mantentzen da, eta automatikoki kargatzen da eskaera bakoitzean.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiatu Segurtasun Gunean','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI ezaugarriak aktibatzeko aukera ematen duen WordPress gaitasun minimoa. Honek multi-autor guneetan murrizten du, Kontribuzioak edo proba kontuak AI bidezko deien kostuak saihesteko. Gainbegiratu ezazu funtzioen arabera linguaforge_required_capability filter bidez.','Maintenance'=>'Mantentze-lanak','Maintenance Tab'=>'Mantentze Fitxa','Make casual'=>'Egin informaleago','Make concise'=>'Egin labur','Make formal'=>'Egin formalago','Mark citations needed'=>'Markatu aipuak behar direla','Max context characters'=>'Testuinguru maximoa','Max hints characters'=>'Gomendioen karaktere maximoa','Max input characters'=>'Max karaktere input','Max output tokens'=>'Max tokens output','Maximum characters accepted from the input field. Default: 8 000.'=>'Sarrerako eremuak onartzen dituen karakter kopururik handiena. Lehenetsia: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'AIri pasatzen zaion edukia, gomendiorik ez dagoenean, hazi testuinguru gisa. Lehenetsia: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Gomendioen eremutik irakurritako karaktere maximoa. Lehenetsia: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Postaren edukia bidali zaion karakter kopururik handiena. 0 ez du mugarik — beti bidaltzen da edukia osoa (gomendatua). Ezarri balio ez-zeroa zure hornitzaileak testuinguru leiho estu bat duenean. Abisua PHP errore erregistroan idazten da edukia moztu denean.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Max tokens kopurua AIk ekoiztu dezakeen itzulpen erantzun batean. Itzulpen bat isilpean moztu bada, handitu balio hau. Lehenetsia: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AI-k ekoiztu dezakeen token kopururik handiena sortze bakoitzeko. Handitu hori, artikulu osoak moztu gabe geratzen direnean. Lehenetsia: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI-k ekoiztu dezakeen token kopururik handiena itzulpen azkar bakoitzeko. Lehenetsia: 2.000.','Meta Description'=>'Meta Deskribapena','Meta description'=>'Meta deskribapena','Meta Description, Excerpt Generator'=>'Meta Deskribapena, Laburpen Sortzailea','Metric'=>'Metrika','Minimum role'=>'Gutxieneko rola','Missing pattern name or language.'=>'Patroiaren izena edo hizkuntza falta da.','Mode'=>'Modua','Model'=>'Eredua','Model tier'=>'Modelo maila','Models'=>'Modeloak','Models Tab (General)'=>'Modeloak Fitxa (Orokorra)','Modified'=>'Aldatuta','Most recent cached block'=>'Azkeneko cacheko blokea','Most recent cached response'=>'Azkeneko cacheko erantzuna','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Hizkuntza anitzeko bidea, SEO anitzeko hizkuntza anitza (hreflang, Open Graph, Schema.org, sitemap), eta AI edukien tresnak WordPressentzat. Hizkuntza detekzioa, URL bidea, itzulpena, edukien sortzea, eta SEO geruza osoa — ez da beharrezkoa plugin laguntzailea.','Name displayed in this language. Leave empty to use the source name.'=>'Izena hizkuntza honetan erakutsia. Utzi hutsik itzultzaile izena erabiltzeko.','Navigation'=>'Nabigazioa','Navigation has no content to translate.'=>'Nabigazioak ez du itzultzeko edukiarik.','Navigation not found.'=>'Nabigaziorik ez da aurkitu.','Navigation posts are translated via the Router tab, not this button.'=>'Nabigazio mezuak Router fitxan itzultzen dira, ez botoi honetan.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Nabigazioaren itzulpena AI hornitzaile aktibo baten beharra du. Konfiguratu API giltza API Giltzen fitxan.','Navigations'=>'Nabigazioak','Network error — could not reach the WordPress AJAX endpoint.'=>'Sareko errorea — ezin izan da WordPress AJAX puntura iritsi.','No %s version found in this translation group.'=>'Ez da %s bertsio bat aurkitu itzulpen talde honetan.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Ez da ekintza behar. Google-k bere sitemap ping endpoint-a deprecated egin du 2024ko urtarrilean eta orain sitemap-ak soilik robots.txt Sitemap: direktiboa erabiliz aurkitzen ditu — hau dagoeneko konfiguratu du LF-k. Google-k hurrengo arakatzean hautemango du.','No AI provider configured.'=>'AI hornitzaile konfiguratu gabe.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Ez dago AI hornitzaile konfiguraturik. Gehitu API giltza Ezarpenak → API Giltzak atalean.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Ez da AI erabilerarik erregistratu aukeratutako leihoan (%s). Aukeratu goiko zabalagoa.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Oraindik ez da AI erabilerarik erregistratu. Behin editore batek itzulpena egin, meta deskribapena sortu edo beste AI ezaugarri bat erabili, totala hemen agertuko da.','No API key configured for this provider.'=>'Ez dago API gako konfiguraturik hornitzaile honetan.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Ez da prestatutako ezarpenik — AI ezaugarriek beren ezarpenak erabiltzen dituzte. Bete beheko Pertsonalizatutako aginduen eremua zure webguneko arau propioak gehitzeko.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Ez dago kontrako SEO pluginik detektatu. Lingua Forge-k SEO irteera guztia modu independentean kudeatzen du.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Oraindik ez da Loco Translate fitxategirik aurkitu. Itzulpena gordetzen duzunean agertzen da hemen.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Ez dago kanpoko OG pluginik detektatu. LF-k OG + Twitter Card osotasuna ematen du.','No file was selected.'=>'Ez da fitxategirik aukeratu.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Ez dago oraindik filtroarekin bat datorren glossario sarrerarik. Garbitu filtroa guztiz ikusteko edo sartu berri bat gehitzeko behean.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Oraindik ez dago glossario sarrera. Gehitu behean terminologia betetzeko itzulpenetan.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Ez da H1 aurkitu. Normalean, postaren izenburua H1 da — egiaztatu zure gaia hori ematen duela.','No images found in content.'=>'Ez da irudiak aurkitu edukiaren barruan.','No internal links found to update.'=>'Ez da barruko estekarik egon eguneratzeko.','No language-specific template parts found to map.'=>'Ez da hizkuntza-espezifikoak diren txantiloia zatiak aurkitu mapatzeko.','No LF meta description set — using excerpt/content.'=>'Ez da LF meta deskribapenik ezarri — pasartea/edukia erabiliz.','No links found.'=>'Ez da linkik aurkitu.','No links found. Internal links improve crawlability and user navigation.'=>'Ez da estekarik aurkitu. Barruko estekek arakatzeko eta erabiltzailearen nabigazioa hobetzen dute.','No meta description found. Generate one via the AI meta description feature.'=>'Ez da meta deskribapenik aurkitu. Sortu AI meta deskribapenaren ezarpenaren bidez.','No navigation references needed updating.'=>'Ez da nabigazio erreferentziarik egon eguneratzeko.','No override files uploaded yet.'=>'Oraindik ez da ordezkaritza fitxategirik kargatu.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Ez da robots.txt fitxategi fisikorik aurkitu. WordPress-ek birtualki sortzen du eta LF-ren Sitemap direktiba automatikoki sartzen da.','No published posts found for the selected filters.'=>'Ez da argitaratutako postik aurkitu hautatutako iragazkietan.','No response from AI provider. Check your API key and try again.'=>'Ez da AI hornitzailearen erantzunik jaso. Egiaztatu zure API giltza eta saiatu berriro.','No response from provider — check the error log for details.'=>'Hornitzailearen erantzunik ez — egiaztatu errore erregistroa xehetasunak egiteko.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Ez dago bigarren hizkuntzarik konfiguraturik. Instalatu hizkuntza paketea goian, txantiloiak sortzeko aukera emateko.','No source content found to translate.'=>'Ez da itzultzeko iturri edukirik aurkitu.','No source page linked yet.'=>'Oraindik ez dago iturri orririk lotuta.','No template part references needed updating.'=>'Ez da eguneratzeko behar diren txantiloia zatiaren erreferentziarik.','No title set.'=>'Ez da izenbururik ezarri.','No translated content found. The sitemap will populate once posts have been translated.'=>'Ez da itzulitako edukiarik aurkitu. Sitemapa beteko da orriak itzuli direnean.','No translation found — analyzed the source language version.'=>'Ez da itzulpenik aurkitu — aztertu iturri hizkuntzako bertsioa.','No {lang} translation registered (TRID missing)'=>'Ez dago {lang} itzulpenik erregistratuta (TRID falta)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Oraindik sortu gabe. Sitemapa lehen bisitan sortzen da eta 24 orduz cache-atzen da.','Notes'=>'Oharra','Nothing — all types disabled'=>'Ez da ezer — mota guztiak desgaituak','Notice message'=>'Ohar mezua','Notice settings'=>'Ohar ezarpenak','Notify search engines'=>'Jakinarazi bilatzaileei','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card etiketak: LF-ren Open Graph moduluak kudeatzen du (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Guztien zaharrena cacheko blokea','Oldest cached response'=>'Guztien zaharrena cacheko erantzuna','Only .mo files are accepted.'=>'Only .mo fitxategiak onartzen dira.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Open Graph output'=>'Open Graph irteera','Open Graph settings saved.'=>'Open Graph konfigurazioak gorde dira.','Open Search Console →'=>'Open Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Ireki nabigatzailearen Web Share orri naturala (iOS, Android, batzuk mahaigainekoak). Berriro ere, ez badago, itsatsi arbelean.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Aukerazko testuingurua editoreentzat (adibidez, "ASIC = Application-Specific Integrated Circuit; ingelesean gorde tekniko testuinguruetan").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Aukerakoa. Bing-ek jada irakurtzen du Sitemap: direktiba robots.txt-tik — hau berehala berridazteko aukera ematen du, hurrengo egutegiko azterketarako.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Aukerakoa. Yandex-ek jada irakurtzen du Sitemap: direktiba robots.txt-tik — hau berehala berridazteko aukera ematen du, hurrengo egutegiko azterketarako.','Output'=>'Irteera','Output Article or WebPage schema on singular posts and pages'=>'Artikulu edo WebPage schema bat ematen du singular post eta orrietan','Output hreflang tags in wp_head'=>'Hitzordua wp_head-n','Output mode'=>'Irteeraren modua','Output Open Graph tags in wp_head'=>'Open Graph etiketak wp_head-n','Output Product schema on WooCommerce product pages'=>'Produktua schema ematen du WooCommerce produktuen orrietan','Output Schema.org JSON-LD in wp_head'=>'Sarrera Schema.org JSON-LD wp_head-en','Output tokens'=>'Irteerako tokenak','Output WebSite schema on the front page and blog index'=>'Sarrera WebSite eskema orria hasieran eta blogaren zerrendan','Overall SEO score'=>'SEO orokorra puntuazioa','overridden'=>'gainditua','Override file deleted.'=>'Ordezkatzeko fitxategia ezabatu da.','Override file uploaded successfully.'=>'Orriaren ordezkoa arrakastaz kargatu da.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Beste ezaugarri guztiak beti erabiltzen dute lehenetsia globala.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Gune osoan konfiguratutako prompt-eskakizunak (Ezarpenak → Portaera) beti gehitzen dira eskaera bakoitzean, aukeraketa honetatik independentea.','Overview'=>'Orokorra','Page'=>'Orria','Part'=>'Zatia','Paste a footnote, sentence, or any snippet here…'=>'Itsatsi ohar, esaldi edo zati hau...','Paste text, or select text in the editor first…'=>'Itsatsi testua, edo hautatu testua editorean lehen…','Paste text, or select text on the page first…'=>'Itsatsi testua, edo hautatu testua orrialdean lehen…','Paste your API key…'=>'Itsatsi zure API giltza…','Path prefix — example.com/de/'=>'Bide-izena — example.com/de/','Pattern'=>'Patron','Pattern has no content to translate.'=>'Ez dago itzuli beharreko edukirik patroiak.','Pattern not found.'=>'Ez da patroiarik aurkitu.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroia itzuli eta gorde da. Edukia zure CPT postean kopiatzailearen bidez edo Erabilerako Blokearen sarreran erabili edo Erabilerako Blokearen hasierako puntutzat erabili.','Pattern translation failed.'=>'Patroiaren itzulpena huts egin du.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Mezua-kopurua cache per-post AI-k sortutako itzulpenentzat, meta-deskribapenentzat, laburpenentzat eta edukientzat. Beti aktiboa — ez da toggle berezirik behar. Sarrera automatikoki baliogabetzen dira edukia edo AI hornitzailea/modelo aldatu ahala.','Permalink rules flushed successfully.'=>'Permalinka arauak arrakastaz bideratu dira.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Ezabatu behin betiko hizkuntza honi lotutako txantiloi guztiak, txantiloien zatiak, ereduak, nabigazio menuak, postak, orriak, post motak, produktuak eta produktu aldaketak. Era berean, WordPress lurralde pakete fitxategiak ezabatzen ditu, hizkuntza hau routerrean agertzen ez dadin. Ekintza hau ezin da desegin.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Ezabatu behin betiko %s? Honek hizkuntza honetan itzulitako edukia guztia ezabatuko du eta ezin da desegin.','Permission denied.'=>'Baimena ukatua.','Persuasive'=>'Beldurgarria','PHP constant'=>'PHP konstantea','Pin on Pinterest'=>'Pin Pinterest-en','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Terminoak pinatu behar dira itzuli ez daitezen edo beti modu jakin batean itzuli behar direnak (adibidez, marka-izenak, produktuen izenak, akronimoak). Glosarioaren muga AI itzulpen eskaera guztietan inposatzen dira: post itzulpena, meta deskribapena, laburpena, eta FSE txantiloi itzulpena.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Hizkuntza arrunta','Please enter some instructions first…'=>'Mesedez, lehenengo argibide batzuk sartu…','Please enter some text first…'=>'Mesedez, lehenengo testu batzuk sartu…','Plugin'=>'Plugina','Post'=>'Posta','Post not found or not published.'=>'Posta ez da aurkitu edo ez da argitaratu.','Post not found.'=>'Posta ez da aurkitu.','Post on X / Twitter'=>'Posta X / Twitter-en','Post Types'=>'Post Motak','Prefilled from excerpt. Edit to override.'=>'Aldizkariaren zatitik aurretik bete. Aldatu nahi baduzu, editatu.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Prezioa eta eskuragarritasuna beti islatzen dute iturri-hizkuntzako produktua (partekatutako stock eredua). Etiketak soilik ematen dira LF-ren Open Graph moduluak "Full" edo "Auto" moduan ezarrita badago eta SEO plugina gatazkagarririk ez badago.','Primary Language'=>'Hizkuntza Nagusia','Primary language'=>'Hizkuntza nagusia','Primary language saved.'=>'Hizkuntza nagusia gorde da.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Hizkuntza primarioa: zure edukia idatzitako hizkuntza. Itzulpen guztiak honetatik sortzen dira; aldaketa ez du postak mugitzen edo ezabatzen.','Processing…'=>'Prozesatzen…','Product'=>'Produktua','Product / eCommerce'=>'Produktua / ECommerce','Product Open Graph'=>'Produktuen Open Graph','Product — WooCommerce product pages'=>'Produktua — WooCommerce produktuen orriak','Profile'=>'Profila','Provider'=>'Hornitzailea','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Hornitzaileak ez du testurik itzuli. Egiaztatu WordPress errore erregistroa huts eginaren arrazoi zehatza ikusteko.','Quality'=>'Kalitatea','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (lehentasuna — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kalitatea: erabiltzen da post itzulpen eta edukien sorkuntzarako — kalitate handiagoa, kostu handiagoa.','Quick Translate'=>'Azkar itzulpena','Quick Translation'=>'Azkar Itzulpena','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Azkar Itzulpena erabilia da zatitxo/modu laburretan — pasarte laburrek eskaeraz itzultzen dira tresnabarra, editorea edo blokea popoverak erabiliz. Konfigurazio arinagoa erabiltzen du, orri osoaren itzulpenetik, erantzunak azkarrago eta kostu txikiagoa izan dadin.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg-en canLockBlocks berriro aktibatzen du. Edizio txantiloietan erabilgarria da, kolaboratzaileek bloke zehatzak mugitu edo ezabatu ez ditzaten.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Re-enables supportsTemplateMode. Oinarrizko lan-fluxuak, non post mailako txantiloiak ukitzen diren, helburu da.','Re-generates and updates the cached result.'=>'Emaitza cache-a berriro sortzen eta eguneratzen du.','Re-scan'=>'Birbideratu','Re-scanning…'=>'Berrikuspen…','Re-translate'=>'Berriz itzuli','Reading time'=>'Irakurketa denbora','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Bisitzaileak birzirkulatu bere nabigatzailearen Accept-Language goiburua oinarrituta','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'hobetu gehiago — adibidez "laburtu egin" edo "erabili tonu formal bat"…','Refine further:'=>'Hobetu gehiago:','Refinement'=>'Hobekuntza','Refinement failed — please try again.'=>'Hobekuntza huts egin da — mesedez saiatu berriro.','Refining…'=>'Hobetu…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPressen berridazketa arauak berriro sortzen ditu URL-aren aurkezpenak, hizkuntza-espezifikoak eta artxibo berridazketak bat etortzeko. Oinarrizko hizkuntza aldatzean edo hizkuntza berriak gehitzean beharrezkoa.','Remove stored key'=>'Ezabatu gakoa gordeta','Report an issue on GitHub'=>'Txostena GitHub-en','Request failed — please try again.'=>'Eskakizuna huts egin du — mesedez saiatu berriro.','Request failed.'=>'Eskakizuna huts egin du.','Request failed. Check your connection.'=>'Eskakizuna huts egin du. Egiaztatu zure konexioa.','Request failed. Please try again.'=>'Eskakizuna huts egin du. Saiatu berriro.','Requests'=>'Eskaerak','Reset'=>'Berrezarri','Result will appear here…'=>'Emaitza hemen agertuko da…','Retranslate'=>'Itzuli berriro','Retranslating…'=>'Itzultzen berriro…','Review carefully — links and slugs not updated.'=>'Aztertu arretaz — estekak eta slugak ez dira eguneratu.','Review translation before applying'=>'Aztertu itzulpena aplikatu baino lehen','Revise'=>'Berrikusi','Revision'=>'Berrikuntza','Revision Type'=>'Berrikuntza mota','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt eguneratu da Sitemap direktibarekin.','Router'=>'Router','Router Tab'=>'Router-aren Fitxa','Run AI Analysis'=>'Exekutatu AI Analisia','Save analysis settings'=>'Gorde azterketa ezarpenak','Save Debug Setting'=>'Gorde Debug Konfigurazioa','Save Hreflang Settings'=>'Gorde Hreflang Ezarpenak','Save Open Graph Settings'=>'Gorde Open Graph Ezarpenak','Save Router Settings'=>'Gorde Router-ezintzak','Save Schema.org Settings'=>'Gorde Schema.org Ezarpenak','Save Settings'=>'Gorde Ezarpenak','Save Sitemap Settings'=>'Gorde Sitemap Ezarpenak','Save Social Share Settings'=>'Gorde Gizarte Partekatze Ezarpenak','Save the post to persist changes.'=>'Gorde mezua aldaketak gorde ahal izateko.','Save Uninstall Setting'=>'Gorde Desinstalazio Ezarpena','Save WooCommerce SEO Settings'=>'Gorde WooCommerce SEO Ezarpenak','Saved to the meta description field when you apply.'=>'Gorde meta deskribapen eremuan aplikatzen duzunean.','Scan failed: '=>'Eskaneaketa huts egin du: ','Scan request failed. Please try again.'=>'Eskaneatzeko eskaera huts egin du. Saiatu berriro.','Scanning posts for broken language links…'=>'Hitz egiten ari diren postak hizkuntza loturak hausten saiatzen…','Schema output deferred.'=>'Schema output-a atzeratu da.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org output','Schema.org settings saved.'=>'Schema.org ezarpenak gorde dira.','Search'=>'Bilaketa','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console erabilgarria da indexazio eta estaldura akatsak monitorizatzeko, baina ez da beharrezkoa aurkitzeko.','Search Results'=>'Bilaketa emaitzak','Security check failed — file path is not permitted.'=>'Segurtasun kontrola huts egin du — fitxategiaren bidea ez da baimendua.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Hautatu hizkuntza, bere FSE txantiloiak, zatiak eta nabigazio menuak kudeatzeko.','Select language'=>'Hizkuntza hautatu','Send via Telegram'=>'Bidali Telegram bidez','Send via WhatsApp'=>'Bidali WhatsApp bidez','SEO'=>'SEO','SEO Analysis'=>'SEO Analisia','SEO character-count info'=>'SEO karakter-kopurua informazioa','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO plugina(ak) detektatuak: %s. LF-k og:locale eta og:locale:alternate bakarrik ematen ditu; detektatutako plugina osoko OG multzoa kudeatzen du.','SEO plugins and conflict avoidance:'=>'SEO pluginen eta gatazkak saihesteko:','SEO Tab'=>'SEO Fitxa','Server setup (subdomain)'=>'Zerbitzariaren konfigurazioa (azpigunea)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'AIren portaera lehenetsia ezartzen du webgune osoan. Post bakoitzak aldatu dezake Translatio eta Eduki Sortzailearen bidez Lingua Forge meta kutxa erabiliz.','Settings'=>'Ezarpenak','Settings saved.'=>'Ezarpenak gorde dira.','Share on Facebook'=>'Partekatu Facebook-en','Share on LinkedIn'=>'Partekatu LinkedIn-en','Share on Mastodon'=>'Partekatu Mastodon-en','Share via email (mailto:)'=>'Partekatu email bidez (mailto:)','Show home link'=>'Erakutsi hasierako esteka','Shown when no translation exists for the visitor\'s language.'=>'Ez dago itzulpenik bisitariaren hizkuntzarako.','Single'=>'Bakarra','Single %s'=>'Bak %s','Single: %s'=>'Bak: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'AI eskaerak UTC egunean (biak Toolbar itzulpenak eta blokeko berrikuspenak) muga. Kontagailua UTC erdian berritzen da. Utzi 0, muga desgaitu nahi baduzu.','Sitemap'=>'Sitemap','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Sitemap cachea hustu da. Hurrengo bisitan sitemap URL-an berriz sortuko da.','Sitemap output'=>'Sitemap output-a','Sitemap settings saved.'=>'Sitemap ezarpenak gorde dira.','Sitemap URL'=>'Sitemap URL','Size'=>'Tamaina','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Gizarte Ikonoen blokea partekatzea: URL-ak: LF-ren Gizarte Partekatze (SEO → Gizarte Partekatze) eraikitakoak','Social Share'=>'Gizarte Partekatzea','Social Share settings saved.'=>'Gizarte Partekatze ezarpenak gorde dira.','Some link fixes failed.'=>'Etxe batzuk konponketak huts egin dute.','Some nav ref fixes failed.'=>'Nabigazio erreferentziak konponketak huts egin dute.','Some part fixes failed.'=>'Atal batzuk konponketak huts egin dute.','Some parts could not be created.'=>'Etxe batzuk ezin izan dira sortu.','Some templates could not be created.'=>'Etxe batzuk ezin izan dira sortu.','Some translations failed.'=>'Itzulpen batzuk huts egin dute.','source'=>'iturria','Source file not found.'=>'Iturri fitxategia ez da aurkitu.','Source lang'=>'Iturri hizkuntza','Source language'=>'Hizkuntza iturriaren','Source term'=>'Iturri terminoa','Standard'=>'Estándarra','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standardak ezaugarri bakoitzaren tenperatura egokituaren erabilera du: Itzulpena T=0.2 ( zehatza), Azkar Itzulpena T=0.4, Eduki Sortzailea T=0.6 (kreatiboa). Beste aurrekoak tenperatura finkoa aplikatzen du ezaugarri guztietan.','Status'=>'Egoera','Status / Actions'=>'Egoera / Ekintza','Storytelling'=>'Istorioak','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Lege, araudi, mediku edo tekniko edukiaren gordetzeko modua. Aktibatzen denean, AI ezaugarri bakoitzak tenperatura baxu bat erabiltzen du eta behean gehitzen du sistema prompt-aren azpian — terminologia, artikulu zenbakiak, unitateak, marka izenak eta araudi hizkuntza bertan bertan gordetzen dira, ez paragrafatuak.','Structured Outline'=>'Eskema antolatu','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Azpi-domein moduak zure web zerbitzariari eskatzen dio azpi-domein hizkuntzak (adibidez, de.example.com) WordPress instalazio honetara zuzentzea. Moduak aldatzean, permalinka arauak bota eta cache-ak garbitu. Zure hasierako URL-an www badago (adibidez, www.example.com), lf_base_domain iragazkia erabili domeinaren goiko maila ezkutatzeko, azpi-domeinak era egokian eraikitzeko.','Subdomain — de.example.com/'=>'Azpi-domein — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Bidali URL hau Google Search Console-era zure sitemap nagusiarekin batera.','Submit to Reddit'=>'Bidali Reddit-era','Suggested meta description'=>'Meta deskribapen proposatua','Suggested title'=>'Izenburua proposatua','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Hornitzaile onartuak: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Batek baino gehiagok ez dute aktiboa aldi berean. Hautatu aktibo dagoen hornitzailea Orokorreko fitxan.','Suppressed: %s.'=>'Ezgaitu da: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ezaugarri bakoitzeko','Tag'=>'Etiketa','Tags emitted'=>'Ekarritako etiketak','Target lang'=>'Helburu hizkuntza','Target Language'=>'Hizkuntza Helburu','Target language'=>'Helburu hizkuntza','Target term'=>'Helburu terminoa','Target: 140–160 chars for optimal SERP display'=>'Helburua: 140–160 karakter SERP-n ondo erakusteko','Technical'=>'Teknikoa','Technical / Scientific'=>'Teknikoa / Zientzia','Technical / Scientific instructions'=>'Tekniko / Zientziazko argibideak','Template "%s" already exists.'=>'"%s" jada existitzen da.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'"{expected}" izeneko txantiloi ez da existitzen — sortu lehenengo Gune Editorean.','Template has no content.'=>'Txantiloian ez dago edukirik.','Template mode'=>'Txantiloi modua','Template not found or not stored in the database.'=>'Txantiloia ez da aurkitu edo ez da datu-basean gordeta.','Template part "%s" already exists.'=>'"%s" zatia jada existitzen da.','Template part has no content.'=>'Ez dago edukirik txantiloia zatian.','Template part not found or not stored in the database.'=>'Ez da txantiloia zatiaren erroa edo ez da gordeta datu-basean.','Template Parts'=>'Txantiloien Zatiak','Templates'=>'Txantiloiak','Test connection'=>'Testatu konexioa','Testing…'=>'Testing…','Text domain / locale'=>'Testu domeinua / hizkuntza','Text to translate'=>'Itzuli beharreko testua','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API Erantzun Cacheak AI eskaeraren emaitza gordetzen du — itzulpena, meta deskribapena, laburpena, eta edukia — sarrera hash baten bidez (edukia, hizkuntza pareta, hornitzailea, modelo). Eskari jarraituak, sarrerak berdinak badira, cachetik ematen dira API de beharrik gabe. Cachea ez da Itzulpen Memoria: Itzulpen Memoria bloke mailakoa da eta partekatua da post guztien artean; API Erantzun Cachea ez da ezaugarri mailakoa eta post bakoitzeko giltza du.','The editor did not accept the content — please try again.'=>'Editoreak ez zuen edukia onartu — mesedez saiatu berriro.','The following directive is active in your virtual robots.txt:'=>'Hurrengo zuzendaritza aktibo dago zure robots.txt birtualean:','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-plugin aktibo dago.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-plugin aktibo dago. Lingua Forge-ren Gizarte Partekatze integratua ez dago aktibo — mu-pluginak partekatze URLak berridatzi eta JS ekintzak kudeatzen ditu.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Arin mailak model azkarrena erabiltzen du goiko Modeloak taulan konfiguratutako moduan (lehena: Haiku / Flash). Aldatu Kalitatera, zatitxoetan orri osoaren itzulpenaren zehaztasuna behar duzunean.','The phrase as it appears in the source text.'=>'Iturri testuan agertzen den esamena.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Hizkuntza nagusia beti zerbitzatzen da zure gunearen erroan — ez URL aurrizkia bide moduan, ez hizkuntza azpian domeinua moduan. Beste hizkuntzak edo /lang/ bide aurrizkia (adibidez example.com/de/) edo hizkuntza azpian domeinua (de.example.com) erabiltzen dituzte, beheko URL egitura ezarpenaren arabera.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Konpatibilitate fitxak bizirik dagoen detekzio egoera erakusten du eta zehatz-mehatz azaltzen du LF zer egiten duen ezaugarri bakoitzerako.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Partekatze URLak beti orriaren unea islatzen du — ez da URL eskuz sartzerik behar. linguaforge_social_share_url iragazkia erabili dezakezu edozein zerbitzurarako URL konponduena gainditzeko.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Sitemap-a automatikoki iragazkia.txt-n iragartzen da. Bilaketa motor nagusiak — Google, Bing, Yandex — bertatik ezagutzen dute. Ez da eskuzko bidalketa behar.','The source page has no footnotes.'=>'Iturri orriaren ohar-oinik ez dago.','The upload failed — please try again.'=>'Kargatzea huts egin du — saiatu berriro.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPress-eko sitemap nagusia zure edukiaren URL guztiak zerrendatzen ditu. LF sitemap-ek nola erlazionatzen diren hizkuntza bertsioak xhtml:link hreflang alternatiben bidez adierazten du. Bidali biak Google Search Console-era estaldura osoa lortzeko.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ohar-oin hauek iturri orritik datoz eta hemen agertzen dira erreferentzia gisa soilik. Gehitu hauek orri honetan blokea editorea erabiliz.','This is the source page. Footnotes are edited directly in the block editor.'=>'Hau da iturri orria. Ohar-oinak zuzenean editatzen dira blokea editorean.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Gakoa hau une honetan zerbitzariko %s batek hornitzen du eta ezin da hemen ezabatu. Sartu gakoa goian gainean eta datu-baseko balio batekin ordezkatu.','This language is protected and cannot be uninstalled.'=>'Hizkuntza hau babestuta dago eta ez da desinstalatu daiteke.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Hizkuntza hau WordPress-eko lokalizazioarekin bat dator eta ez da desinstalatu daiteke.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: modelo bat lehenetsira berrezartzeko, garbitu eremua eta gorde.','Title'=>'Izenburua','Title is %1$d chars — aim for %2$d–%3$d.'=>'Izenburua %1$d karaktere — helburu %2$d–%3$d da.','Title is %1$d chars — may be truncated in SERPs (aim for %2$d–%3$d).'=>'Izenburua %1$d karaktere da — SERP-etan moztu daiteke (helburua %2$d–%3$d).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Erabili nahi duzun enkriptazio sekretu pertsonalizatua (wp_salt balioa lortzeaz gain), gehitu hau wp-config.php-ra:','Today'=>'Gaur','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Token kontsumoa ezaugarri, hornitzaile eta ereduen arabera biltzen da. Erregistratzen da AI deien arrakasta bakoitzean; Test konexio pingak ez dira barne hartzen, beraz, ez dute guztiz aldatzen.','Tone'=>'Tona','tone'=>'tonu','Tone:'=>'Tonua:','Too many AI requests. Please retry in %d seconds.'=>'AI eskaera gehiegi. Saiatu berriro %d segundo barru.','Total'=>'Guztira','Total tokens'=>'Token guztira','Translate'=>'Itzuli','Translate / Revise'=>'Itzuli / Berrikusi','Translate / Revise block'=>'Bloke itzuli / Berrikusi','Translate all'=>'Itzuli guztiak','Translate chunk'=>'Itzuli zatia','Translate Content'=>'Itzuli Edukia','Translate missing'=>'Missing itzuli','Translate page…'=>'Orria itzuli…','Translated content'=>'Itzulitako edukia','Translated Names'=>'Izendapenak itzuli','Translated title'=>'Itzulitako izenburua','Translated to:'=>'Itzuli da:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Itzuli da. Ikuskaritza-sarean berrikusi — lotura barneak, nabigazio URL-ak eta txantiloiaren slug-ak ez dira automatikoki eguneratzen.','Translating…'=>'Itzultzen…','Translation'=>'Itzulpena','Translation Caching'=>'Itzulpenaren cachea','Translation found but permalink could not be generated'=>'Aurkitu da translatzea baina permalink-a ezin izan da sortu','Translation Limits'=>'Itzulpen Muga','Translation Limits & Behavior'=>'Itzulpenaren mugak eta portaera','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Itzulpenaren mugak: kontrolatu zein erabiltzaile rolek aktibatu dezaketen AI itzulpena, eta ezarri hilean tokens kopurua. Aurrez aurreko kopurua gaindituz, AI deien erabilera etengo da hilabetea berritzen den arte.','Translation Memory'=>'Itzulpen Memoria','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Itzulpen Memoriak AI emaitzak cacheatzen ditu edukien hash, hizkuntza bikote, hornitzaile eta modelaren arabera. Post bat editatzeak cachea baliogabetzen du, beraz hurrengo itzulpenak emaitza fresko bat jasoko du.','Translation Memory cleared. %d cached block was removed.'=>'Itzulpen Memoria garbitu da. %d cacheatutako blokea kendu da.' . "\0" . 'Itzulpen Memoria garbitu da. %d cacheatutako bloke kendu dira.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Itzulpen Memoria: edukien hasharen arabera post guztia itzuli duena gordetzen du. Garbitu hori, post guztiak berriro itzuli nahi badituzu, edukiak aldatu edo ez.','Translation workflow'=>'Itzulpenaren lan-fluxua','Translation, Content Generator'=>'Itzulpena, Eduki Sortzailea','Treat H2 as H1 equivalent'=>'Treat H2 as H1 equivalent','Type'=>'Mota','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Desinstalatu %s','Uninstall Behaviour'=>'Desinstalazio Portaera','Uninstall setting saved.'=>'Desinstalazio ezarpena gorde da.','unknown error'=>'Errorea ezezaguna','Unknown provider.'=>'Hornitzaile ezezaguna.','Unknown search engine.'=>'Bilaketa-motor ezezaguna.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Hreflang-etik ezberdina da — LF beti gainkargatzen du beste pluginak, zure anitzeko hizkuntzaren konfigurazioa ezagutzen ez dutelako — Open Graph-aren kasuan, Yoast, Rank Math eta antzeko pluginek dagoeneko ematen dituzte zure edukirako OG etiketa egokiak. Bikoiztea ez du baliorik ematen. Modu automatikoan, LF aktibo dauden SEO pluginak detektatzen ditu eta ematen ez dituztenak gehitzen ditu: og:locale (egungo hizkuntza) eta og:locale:alternate (beste hizkuntza guztiak).','Up'=>'Gora','Upload .mo file'=>'Kargatu .mo fitxategia','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Gorde konpilatutako .mo fitxategiak hirugarren aldeko pluginen testuak ordezkatzeko, esaterako, VikBooking itzulpen pertsonalizatua "etxea" ordez "gela" erabiltzen duena. Fitxategiak WordPress izenburuaren arauak jarraitu behar ditu: {textdomain}-{locale}.mo (adibidez, vikbooking-ca.mo). Uploads karpetan gordetzen dira eta plugin eguneraketekin iraun dezakete.','Upload Override'=>'Kargatu Ordezkaketa','URL could not be mapped to a post — check the link target exists'=>'URL ez da mapatu post batera — egiaztatu helburu lotura existitzen dela','URL structure'=>'URL egitura','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL egitura: bide-berri modua (adibide.com/de/) ez du zerbitzariko aldaketarik behar. Azpiburu modua (de.adibide.com) DNS erregistro zabaldu bat, SSL ziurtagiri zabaldu bat eta zerbitzariaren konfigurazio aldaketa bat behar du — ikusi Zerbitzariaren konfigurazio gida.','URL to enter'=>'Sartu URL-a','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Nativako partekatzea erabili baldin badago; kopiatzailearen kopia erabili. Gomendatutako lehenetsia "Partekatzea" botoientzat.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Erabili orriaren goialdeko fitxak konfigurazio bakoitza egiteko. Router fitxan egindako aldaketak berehala aplikatzen dira; AI gakoak eta ereduen konfigurazioak hurrengo AI eskaeran aplikatuko dira.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula terminologikoaren kudeaketa erabiltzaileak hizketa bikoitzeko. Sarrera hauek gehitzen dira itzulpen sistemaren prompt-ean, AI-k termino hobesien erabilera jarraitzeko — dominen hizkuntzako lexikoan oso garrantzitsua ("kWp", "PPA", "interkonexio puntua"), markaren izenak ez dira itzuli behar, eta araudi estandarizatuen formulazioak. Bi hizketa eremuak aukera librekoa dira: utzi "Iturri hizkuntza" hutsik sartu nahi duzun hizkuntzaren araberakoa izan gabe; utzi "Helburu hizkuntza" hutsik, guztietara aplikatzeko.','Using custom meta description.'=>'Metadatu pertsonalizatu bat erabiltzen','Using LF AI meta description.'=>'LF AI meta deskribapena erabiltzen.','Value source'=>'Jatorrizko iturria','View'=>'Ikusi','View built-in default'=>'Ikusi lehenetsia','View current robots.txt'=>'Ikusi momentuko robots.txt','View details'=>'Ikusi xehetasunak','View Lingua Forge details'=>'Ikusi Lingua Forge xehetasunak','Visit plugin site'=>'Bisita ezarpenen webgunea','Warning:'=>'Abisua:','WebSite'=>'Webgunea','WebSite — front page / blog index'=>'Webgunea — hasierako orria / blogaren indexa','What LF provides — and collision avoidance'=>'LF-k ematen duena — eta talka saihestea','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'LF-k ematen duena: hizkuntza bakoitzerako hreflang etiketa, Open Graph eta Twitter Card etiketa og:locale eta og:locale:alternate-rekin, Schema.org JSON-LD inLanguage azpimarraketekin, eta /lf-sitemap.xml-n hizkuntza anitzeko sitemap bat, xhtml:link alternatiba sarrerak dituena guztientzat.','When another SEO plugin is installed'=>'Beste SEO plugin bat instalatuta dagoenean','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Debug log-ak aktibatuta dagoenean (beheko toggle bidez edo wp-config.php-n LINGUAFORGE_AI_DEBUG definituz), Itzulpen eta FSE txantiloi itzulpen ezaugarriak AI prompt eta erantzunak diskoan idazten dituzte arazteak egiteko. Erabili atal hau irteera hori monitorizatzeko eta garbitu behar duzunean — fitxategiak azkar handitzen dira orri handietan. Konfiguratu helbide direktorioa linguaforge_debug_dir iragazkiaren bidez.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Gaituta, lehenengo aldiz bisitatzaileek hizkuntza cookiea edo URL-an hizkuntza aurrebista ez badute, hurbilen dagoen hizkuntza bertsiora birzirkulatuko dira. Birzirkulazioa saihesten da nabigatzailearen hizkuntza aktiboen artean ez badago. Bisitari batek hizkuntza bat hautatzen duenean, cookieak lehentasuna hartzen du eta nabigatzailearen goiburua ez da kontuan hartzen bisita guztietan.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Aktibatuta, sitemap URL-a automatikoki iragartzen da robots.txt-n eta cache-a eguneratzen da itzulitako edukia gordetzen denean.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Yoast SEO, Rank Math, All in One SEO edo SEOPress aktibo badira, Lingua Forge-k automatikoki ezabatzen du haien hreflang irteera filter bidez. SEO plugin orokorrak hreflang sortzen dute URL-aren hizkuntza bakarrean oinarrituta eta ez dute zure anitzeko hizkuntzaren konfigurazioa kontuan hartzen; LF-ren irteera beti zuzena da.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Aktibo dagoen bitartean, mu-pluginak oinarrizko OG multzoa kudeatzen du eta LF-k hizkuntza etiketa soilak (auto moduan) ematen ditu. Ezabatzean, LF-k OG modua osoa aktibatzen du automatikoki.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Zein modelo maila erabili itzulpen osoarentzat. Kalitatea goian ezarritako Modelo taulan konfiguratutako modeloa erabiltzen du eta gomendatzen da zehaztasun handiko, luzeak diren itzulpenetan. Aldatu Argira, azkartasuna edo kostua lehentasuna bada eta edukia laburra bada.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'WooCommerce','WooCommerce'=>'WooCommerce produktuen prezioa','WooCommerce product price'=>'WooCommerce SEO ezarpenak gorde dira.','WooCommerce SEO settings saved.'=>'WooCommerce dendaren moneta','WooCommerce store currency'=>'Hitzen kopurua','Word count'=>'WP core canonical aktibo dago (hreflang desgaituta)','WP core canonical active (hreflang disabled)'=>'XML Sitemap','WP-CLI reference'=>'WP-CLI erreferentzia','Write AI prompts and responses to disk for troubleshooting'=>'AI prompt eta erantzunak diskoan idaztea arazteak egiteko','XML Sitemap'=>'~%d minutuko irakurketa','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Gakoak ere definitu ditzakezu konstante edo ingurune aldagaitzat (adibidez, wp-config.php-n). Iturri horiek automatikoki erabiltzen dira datu-baseko gakoa ez dagoenean oinarrizko baliabide gisa.','You do not have permission to manage these settings.'=>'Ez duzu baimenik ezarpen hauek kudeatzeko.','You do not have permission to read this post.'=>'Ez duzu baimenik irakurtzeko posta hau.','{n} stale path(s)'=>'{n} bide zahar(ra)','~%d min read'=>'— Pluginera atzeratua' . "\0" . '— Pluginera atzeratua','— Any source language —'=>'— Edozein iturri hizkuntza —','— Any target language —'=>'— Edozein helburu hizkuntza —','— Any target —'=>'— Edozein helburu —','— Any —'=>'— Edozein —','— auto-detect —'=>'— auto-detektatu —','— Deferred to plugin'=>'— Pluginera atzeratua','— Disabled'=>'— desgaituta','— Not detected'=>'— Ez da detektatu','— select a language —'=>'— hautatu hizkuntza —','— toggle in Settings → Behavior.'=>'— toggle Ezarpenetan → Portaeran.','← Back'=>'← Atzera','↑ Detected from current post'=>'↑ Uneko postetik detektatua','→ Locale tags only (manual setting)'=>'→ Tokiko etiketak soilik (eskuzko ezarpena)','→ Locale tags only — deferring base OG to plugin'=>'→ Tokiko etiketak soilik — oinarri OG atzeratzen plugin-era','↺ Re-translate'=>'↺ Berriro itzuli','↺ Refine'=>'↺ Hobetu','↺ Refresh'=>'↺ freskatu','↺ Refresh AI Analysis'=>'↺ Berritu AI Azterketa','↺ Refreshing…'=>'↺ Freskatu…','⚠ Borderline'=>'⚠ Muga-lerroa','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ {lang} ez da aurkitu. Ziurtatu itzuli diren post guztiek hizkuntza metadatuan {lang} ezarrita dutela.','⚠ No changes'=>'⚠ Ez da aldaketarik','⚠ No changes — re-scan?'=>'⚠ Ez da aldaketarik — berriro eskaneatu?','✅ Fixed ({n})'=>'✅ Konponduta ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Ez da hautsi edo txantiloiak ez datoz bat aurkitu. Ikusi <strong>{scanned}</strong> post eta orri — guztiak ondo daude. Txantiloi zatien loturak (goiburua, oinarria, alboko barra) ez dira hemen sartzen — erabili Fix Template Parts botoia horiek banan banan egiaztatzeko.','✅ Template fixed'=>'✅ Txantiloa konponduta','✓ %s notified successfully.'=>'✓ %s jakinarazi da arrakastaz.','✓ Active'=>'✓ Aktiboa','✓ Active at /lf-sitemap.xml'=>'✓ Aktiboa /lf-sitemap.xml-n','✓ Active — %d URL entry with language alternates'=>'✓ Aktiboa — %d URL sarrera hizkuntza alternatibekin' . "\0" . '✓ Aktiboa — %d URL sarrera hizkuntza alternatibekin','✓ Active — full OG + Twitter Cards'=>'✓ Aktiboa — OG osoa + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktiboa — tokiko etiketak soilik (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Atal guztiak sortu dira.','✓ All templates created.'=>'✓ Txantiloi guztiak sortu dira.','✓ All translated.'=>'✓ Itzulpen guztiak egin dira.','✓ Configured'=>'Konfiguratu da','✓ Connection OK'=>'✓ Konexioa ondo','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Edukia sortu da — ikusi gainjarri hori berrikusteko, hobetu, eta aplikatzeko.','✓ Done'=>'✓ Eginda','✓ Enabled'=>'✓ Aktibatuta','✓ Good length'=>'✓ Luzera ona','✓ Hreflang active'=>'✓ Hreflang aktiboa','✓ In safe storage'=>'✓ Segurtasun gunean','✓ Language installed.'=>'✓ Hizkuntza instalatu da.','✓ LF outputs'=>'✓ LF irteerak','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF irteerak Artikulua / Web orria / Webgunea','✓ LF outputs full OG + Twitter Cards'=>'✓ LF irteerak OG osoa + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF irteerak — plugin hreflang ezabatuta','✓ Links fixed.'=>'✓ Estekak konponduta.','✓ Nav refs fixed.'=>'✓ Nabigazio erreferentziak konponduta.','✓ Parts fixed.'=>'✓ Atalak konponduta.','✓ Pattern translated.'=>'✓ Patroi itzulita.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Robotak.txt fisikoa aurkitu da. LF-ren Sitemap agindua dago.','✓ Refined — review the updated draft above.'=>'✓ Hobetu da — begiratu goiko zirriborro eguneratua.','✓ Translation saved'=>'✓ Itzulpena gorde da','✓ WP core canonical removed'=>'✓ WP nukleoko canonical ezabatu da','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s pingak ez du funtzionatu. Sitemap URL-a oraindik iragartzen da robots.txt-n — bilatzaileak hurrengo arakatzean ezagutuko du.','✗ Disabled'=>'✗ Desaktibatuta','✗ Error:'=>'✗ Akatsa:','✗ Failed:'=>'✗ Huts egin du: ','✗ Not configured'=>'Ez da konfiguratu','✗ Too long'=>'✗ Oso luze','✗ Too short'=>'✗ Oso laburra','❌ Failed'=>'❌ Huts egin du','📄 Wrong template'=>'📄 Txantiloi okerra','📍 Stale path (page moved)'=>'📍 Bide zahar (orria mugituta)']];
